{{ config(
            materialized='table',
                post_hook={
                    "sql": "drop table if exists public.quickshift_sales_consolidated_Harshal_date; CREATE TABLE public.quickshift_sales_consolidated_Harshal_date AS WITH sales_conso as( select s.*, wm.\"Mapped Warehouse Name\", UPPER(mm.\"Order Type\") AS \"Order Type\", mm.\"Mapped Marketplace Name\", wm.\"Client Name\", ws.mapped_warehouse_status, mcm.mapped_channel, mcm.new_channel, CASE WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN \'MARKETPLACE\' WHEN UPPER(wm.\"Client Name\") = \'GHAR SOAPS\' THEN \'GHAR SOAPS\' WHEN UPPER(s.shipping_provider) LIKE \'%QUICKSHIFT%\' OR (s.shipping_provider IS NOT NULL AND (s.awb IS NULL OR TRIM(s.awb) = \'\') AND UPPER(wm.\"Client Name\") NOT IN (\'SUPER YOU\',\'FAST AND UP\',\'BENNYS BOWL\',\'BENNYS BOWS\')) OR (s.shipping_provider IS NULL AND (s.awb IS NULL OR TRIM(s.awb) = \'\')) THEN \'QS SHIPPING\' WHEN UPPER(s.shipping_provider) NOT LIKE \'%QUICKSHIFT%\' OR (s.shipping_provider IS NOT NULL AND (s.awb IS NULL OR TRIM(s.awb) = \'\') AND UPPER(wm.\"Client Name\") IN (\'SUPER YOU\',\'FAST AND UP\',\'BENNYS BOWL\',\'BENNYS BOWS\')) OR (s.shipping_provider IS NULL AND (s.awb IS NOT NULL)) THEN \'CLIENT SHIPPING\' END AS Harshal_Shipping from public.quickshift_sales_consolidated_intermediate s left join (select * from (select *, row_number() over (partition by \"facility name\" order by \"facility name\") rw from public.gs_warehouse_mapping ) where rw = 1) wm on lower(wm.\"facility name\") = lower(s.warehouse) left join (select * from (select *, row_number() over (partition by channel order by channel) rw from public.Google_sheets_channel_mapping ) where rw = 1) cm on lower(cm.channel) = lower(s.channel) left join (select * from (select *, row_number() over (partition by \"Marketplace Name\" order by \"Marketplace Name\") rw from public.gs_marketplace_mapping ) where rw = 1) mm on lower(mm.\"Marketplace Name\") = lower(s.marketplace) left join (select * from (select *, row_number() over (partition by channel order by channel) rw from public.Google_sheets_channel_mapping ) where rw = 1) mcm on lower(cm.channel) = lower(s.channel) left join (select * from (select \"order status\" as order_status, \"shipping status\" as shipping_status, \"warehouse status\" as mapped_warehouse_status, row_number() over (partition by \"shipping status\",\"order status\" order by 1,2) rw from public.gs_warehouse_status ) where rw = 1) ws on lower(ws.order_status) = lower(s.order_status) and lower(ws.shipping_status) = lower(s.shipping_status) ), Harshal_shipping as( select *, CASE WHEN UPPER(Harshal_Shipping) = \'GHAR SOAPS\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(inventory_assigned_date, order_date)) < 13 THEN DATE_TRUNC(\'DAY\',COALESCE(inventory_assigned_date,order_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD( DAY, 1, DATE_TRUNC( \'DAY\',COALESCE( inventory_assigned_date, order_date) )) + INTERVAL \'13 HOURS\' END WHEN UPPER(Harshal_Shipping) = \'MARKETPLACE\' THEN COALESCE(fulfillment_tat, order_date) WHEN UPPER(\"order type\") = \'B2B\' THEN DATEADD(day, 2, COALESCE(inventory_assigned_date, order_date)) WHEN UPPER(Harshal_Shipping) = \'QS SHIPPING\' OR UPPER(Harshal_Shipping) = \'CLIENT SHIPPING\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(order_date, inventory_assigned_date)) < 13 THEN DATE_TRUNC(\'DAY\', COALESCE(order_date, inventory_assigned_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD(DAY, 1, DATE_TRUNC(\'DAY\', COALESCE(order_date, inventory_assigned_date))) + INTERVAL \'13 HOURS\' END END AS Harshal_Date from sales_conso ), TAT_STATUS AS ( select *, CASE WHEN COALESCE(DATE(DISPATCH_DATE),DATE(ORDER_DATE)) <= DATE(HARSHAL_DATE) THEN \'IN TAT\' ELSE \'OUT TAT\' END AS TAT_STATUS from Harshal_shipping ) SELECT *, CASE WHEN (UPPER(Harshal_Shipping) = \'GHAR SOAPS\' AND UPPER(ORDER_STATUS) IN (\'CANCELLED\',\'RETURNED\')) THEN \'CANCELLED\' WHEN (UPPER(Harshal_Shipping) = \'CLIENT SHIPPING\' AND UPPER(SHIPPING_STATUS) LIKE \'%CANCELLED%\') THEN \'CANCELLED\' WHEN (UPPER(Harshal_Shipping) = \'GHAR SOAPS\' AND (UPPER(SHIPPING_STATUS) IN (\'IN TRANSIT\',\'SHIPMENT CREATED\',\'SHIPMENT LOST\',\'PICK UP\') OR UPPER(SHIPPING_STATUS) LIKE \'%DELIVERED%\' OR UPPER(SHIPPING_STATUS) LIKE \'%DELIVERY%\' OR UPPER(SHIPPING_STATUS) LIKE \'%RTO%\')) THEN \'HANDOVER DONE\' WHEN (UPPER(Harshal_Shipping) = \'CLIENT SHIPPING\' AND UPPER(shippingpackagestatus) IN (\'DELIVERED\',\'SHIPPED\',\'DISPATCHED\',\'RETURNED\',\'RETURN_EXPECTED\')) THEN \'HANDOVER DONE\' WHEN (UPPER(Harshal_Shipping) = \'GHAR SOAPS\' AND (SHIPPING_STATUS IS NULL OR UPPER(SHIPPING_STATUS) = \'SHIPMENT ERROR\' OR UPPER(SHIPPING_STATUS) = \'SHIPMENT ONHOLD\' OR UPPER(SHIPPING_STATUS) LIKE \'%PICKUP%\')) THEN \'HANDOVER PENDING\' WHEN (UPPER(Harshal_Shipping) = \'CLIENT SHIPPING\' AND UPPER(shippingpackagestatus) IN (\'READY_TO_SHIP\',\'PACKED\',\'PICKED\',\'CREATED\',\'PICKING\') OR UPPER(ORDER_STATUS) IN (\'ASSIGNED\',\'CONFIRMED\',\'MANIFEST SCANNED\')) THEN \'HANDOVER PENDING\' WHEN (UPPER(Harshal_Shipping) = \'GHAR SOAPS\' OR UPPER(Harshal_Shipping) = \'CLIENT SHIPPING\') AND UPPER(ORDER_STATUS) IN (\'ON HOLD\',\'UNFULFILLABLE\') THEN \'UNFULFILLABLE\' ELSE UPPER(ORDER_STATUS) END AS Harshal_status FROM TAT_STATUS",
                    "transaction": true
                }
            ) }}
